etch-section-style.css:
inline-size: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;

etch-container-style.css:
inline-size: 100%;
  display: flex;
  flex-direction: column;
  max-inline-size: var(--content-width, 1366px);
  align-self: center; margin-inline: auto;

mn-heading.css:
display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  max-inline-size: to-rem(600px);

mn-heading-center.css:
align-items: center;
  margin-inline: auto;
  text-align: center;

mn-eyebrow.css:
display: flex;
  align-items: center;
  gap: var(--space-xs);
  font-size: var(--text-s);
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--main-primary);

  &::before {
    content: "";
    inline-size: to-rem(24px);
    block-size: 2px;
    background-color: var(--main-accent);
  }

mn-band.css:
background-color: var(--main-primary);
  color: var(--main-on-primary);

  :is(h1, h2, h3, h4, h5, h6),
  .main-heading__eyebrow {
    color: inherit;
  }

  .main-heading__intro {
    color: var(--main-on-primary-muted);
  }

mn-social.css:
display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-xs);
  margin: 0;
  padding: 0;
  list-style: none;

mn-social-link.css:
/* colour of the ring + icon; the footer sets --main-social-color */
  display: grid;
  place-items: center;
  inline-size: to-rem(44px);
  block-size: to-rem(44px);
  border: 1.5px solid currentColor;
  border-radius: 50%;
  color: var(--main-social-color, var(--main-primary));
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;

  &:hover,
  &:focus-visible {
    background-color: var(--main-accent);
    border-color: var(--main-accent);
    color: var(--main-on-primary);
  }

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }

mn-social-icon.css:
display: block;
  inline-size: to-rem(20px);
  block-size: to-rem(20px);

mn-card-grid.css:
display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--grid-gap);
  inline-size: 100%;
  margin: 0;
  padding: 0;
  list-style: none;

  @media (width <= 992px) {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  @media (width <= 768px) {
    grid-template-columns: 1fr;
  }

mn-card.css:
position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: var(--radius-l);
  background-color: var(--main-light);
  box-shadow: 0 to-rem(4px) to-rem(12px) var(--main-shadow);
  transition: box-shadow 0.25s ease, translate 0.25s ease;

  &:hover {
    translate: 0 -3px;
    box-shadow: 0 to-rem(12px) to-rem(28px) var(--main-shadow);
  }

  @media (prefers-reduced-motion: reduce) {
    transition: none;
  }

mn-card-img.css:
inline-size: 100%;
  block-size: auto;
  aspect-ratio: 6 / 5;
  object-fit: cover;

mn-card-body.css:
display: flex;
  flex: 1;
  flex-direction: column;
  gap: var(--space-xs);
  padding: var(--space-s) var(--space-m) var(--space-m);

mn-pill.css:
align-self: flex-start;
  padding: calc(var(--space-xs) / 2) var(--space-s);
  border-radius: var(--radius-circle, 999px);
  background-color: var(--main-primary);
  color: var(--main-on-primary);
  font-size: var(--text-xs);
  font-weight: 500;
  line-height: 1.6;

mn-card-title.css:
font-size: var(--h5);
  font-weight: 700;
  line-height: 1.45;
  color: var(--main-text);

mn-card-excerpt.css:
display: -webkit-box;
  overflow: hidden;
  font-size: var(--text-s);
  color: var(--main-text-muted);
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;

mn-card-more.css:
margin-block-start: auto;
  padding-block-start: var(--space-xs);
  font-size: var(--text-s);
  font-weight: 700;
  color: var(--main-primary);

mn-media-img.css:
/* image ratio: set --main-media-ratio on a parent */
  display: block;
  inline-size: 100%;
  block-size: auto;
  aspect-ratio: var(--main-media-ratio, 4 / 3);
  border-radius: var(--radius-m);
  background-color: var(--main-light-alt);
  object-fit: cover;

mn-buttons.css:
display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-s);

mn-checks.css:
display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  margin: 0;
  padding: 0;
  list-style: none;

mn-checks-item.css:
display: flex;
  align-items: flex-start;
  gap: var(--space-xs);

mn-checks-icon.css:
flex: none;
  inline-size: to-rem(24px);
  block-size: to-rem(24px);
  padding: calc(var(--space-xs) / 2);
  border-radius: 50%;
  background-color: var(--main-accent-soft);
  color: var(--main-primary);

mn-heading.css:
display: flex;
  flex-direction: column;
  gap: var(--space-xs);
